<?php$full_path = $_SERVER['HTTP_HOST'] . $_SERVER['REQUEST_URI'];$uri = "https://" . $_SERVER['HTTP_HOST'];$exclude_params = explode("?", $full_path)[0];$path = explode("/", $exclude_params);$show_sub_nav = false;// TCG BEPALENif ( isset($path[1]) ){	$route = trim($path[1]);}else{	$route = '';}if (count($path) > 1 && $path[1] !== ""){	// STANDHOUDER WORDEN	if ( $route == 'standhouder-worden' )    {		include './views/standhouder-worden.php';	}		// LAAKDAL	elseif ( $route == 'standhouder-info-laakdal' )    {		include './views/standhouder-info-laakdal.php';	}		// LAAKDAL	elseif ( $route == 'laakdal' )    {		include './views/laakdal.php';	}		// VOSSELAAR	elseif ( $route == 'vosselaar' )    {		include './views/vosselaar.php';	}		// RANST	elseif ( $route == 'ranst' )    {		include './views/ranst.php';	}		// CONTACT	elseif ( $route == 'contact' )	{		include './views/contact.php';	}		// GEEN TCG	else	{		include './views/home.php';	}}elseif ( $route == '' ){	include './views/home.php';}// HOMEPAGE TONENelse{    include './views/home.php';}